data.value:
{
    "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
    "type": "AdaptiveCard",
    "version": "1.0",
    "hideOriginalBody": true,
    "originator": "${$root.providerId}",
    "createdUtc": "${$root.cardCreatedTime}",
    "body": [
      {
        "type": "Container",
        "padding": "Small",
        "style": "emphasis",
        "items": [
          {
            "type": "ColumnSet",
            "padding": "None",
            "columns": [
              {
                "type": "Column",
                "padding": "None",
                "width": "auto",
                "items": [
                  {
                    "type": "Image",
                    "url": "data:image/png;base64,",
                    "altText": "Synchronization Exception Icon",
                    "size": "Small"
                  }
                ]
              },
              {
                "type": "Column",
                "padding": "None",
                "verticalContentAlignment": "Center",
                "width": "auto",
                "items": [
                  {
                    "type": "TextBlock",
                    "text": "Membership Change Alert Review",
                    "wrap": true,
                    "weight": "Bolder"
                  },
                  {
                    "type": "TextBlock",
                    "text": "Group Membership Management",
                    "wrap": true,
                    "spacing": "None",
                    "color": "Dark",
                    "size": "Small"
                  }
                ]
              }
            ]
          }
        ]
      },
      {
        "type": "Container",
        "padding": "Default",
        "separator": true,
        "items": [
          {
            "type": "TextBlock",
            "text": "${$root.groupName}",
            "wrap": true,
            "size": "Large",
            "weight": "Bolder"
          }
        ]
      },
      {
        "type": "Container",
        "padding": "Default",
        "items": [
          {
            "type": "TextBlock",
            "text": "The most recent attempt to update the membership of your GMM managed group '**${$root.groupName}**' exceeded the configured alert threshold.GMM will stop syncing this group by the end of {{DATE(${$root.disableDate}, SHORT)}}. If no action is taken by {{DATE(${$root.purgeDate}, SHORT)}} GMM will purge this sync.  At that point, if you wish to re enable the sync, you will need to follow GMM's onboarding process again.  Please reach out to the **CC'ed alias** for inquiries about re-onboarding or any questions you may have.",
            "wrap": true,
            "color": "Attention"
          },
          {
            "type": "TextBlock",
            "text": "GMM has identified **${$root.changeQuantityForAdditions}** members to be added, increasing the group size by **${$root.changePercentageForAdditions}%**, which is more than the current additions threshold of **${$root.thresholdPercentageForAdditions}%**.",
            "wrap": true,
            "spacing": "Small",
            "color": "Accent",
            "$when": "${$root.changePercentageForAdditions > $root.thresholdPercentageForAdditions}"
          },
          {
            "type": "TextBlock",
            "text": "GMM has identified **${$root.changeQuantityForRemovals}** members to be removed, decreasing the group size by **${$root.changePercentageForRemovals}%**, which is more than the current removals threshold of **${$root.thresholdPercentageForRemovals}%**.",
            "wrap": true,
            "spacing": "Small",
            "color": "Accent",
            "$when": "${$root.changePercentageForRemovals > $root.thresholdPercentageForRemovals}"
          },
          {
            "type": "TextBlock",
            "text": "Do you want to proceed?",
            "wrap": true,
            "color": "Accent",
            "size": "Default",
            "weight": "Bolder"
          },
          {
            "type": "ActionSet",
            "actions": [
              {
                "type": "Action.Http",
                "title": "No, Pause Sync Job",
                "method": "POST",
                "url": "https://${$root.apiHostname}/api/v1/notifications/${$root.notificationId}/resolve",
                "body": "{\"resolution\":\"Paused\"}",
                "isPrimary": true,
                "style": "positive"
              },
              {
                "type": "Action.Http",
                "title": "Yes, Apply Changes",
                "method": "POST",
                "url": "https://${$root.apiHostname}/api/v1/notifications/${$root.notificationId}/resolve",
                "body": "{\"resolution\":\"IgnoreOnce\"}"
              }
            ],
            "spacing": "Large"
          },
          {
            "type": "Container",
            "padding": "Medium",
            "separator": true,
            "items": [
              {
                "type": "TextBlock",
                "text": "**${$root.thresholdPercentageForAdditions}% increase** and **${$root.thresholdPercentageForRemovals}% decrease** alerts are configured for this group. If you would like to change these alert percentages or disable them, please pause the sync and contact GMM support for further inquiry.",
                "wrap": true
              }
            ],
            "spacing": "Medium"
          }
        ],
        "separator": true
      }
    ],
    "autoInvokeAction": {
      "method": "POST",
      "url": "https://${$root.apiHostname}/api/v1/notifications/${$root.notificationId}/card",
      "body": "",
      "type": "Action.Http"
    }
  }

{
 "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
 "type": "AdaptiveCard",
 "version": "1.0",
 "hideOriginalBody": true,
 "originator": "${$root.providerId}",
 "createdUtc": "${$root.cardCreatedTime}",
 "body": [
  {
   "type": "Container",
   "padding": "Small",
   "style": "emphasis",
   "items": [
    {
     "type": "ColumnSet",
     "padding": "None",
     "columns": [
      {
       "type": "Column",
       "padding": "None",
       "width": "auto",
       "items": [
        {
         "type": "Image",
         "url": "data:image/png;base64,",
         "altText": "Synchronization Exception Icon",
         "size": "Small"
        }
       ]
      },
      {
       "type": "Column",
       "padding": "None",
       "verticalContentAlignment": "Center",
       "width": "auto",
       "items": [
        {
         "type": "TextBlock",
         "text": "Synchronization Job Disabled",
         "wrap": true,
         "weight": "Bolder"
        },
        {
         "type": "TextBlock",
         "text": "Group Membership Management",
         "wrap": true,
         "spacing": "None",
         "color": "Dark",
         "size": "Small"
        }
       ]
      }
     ]
    }
   ]
  },
  {
   "type": "Container",
   "padding": "Default",
   "separator": true,
   "items": [
    {
     "type": "TextBlock",
     "text": "${$root.groupName}",
     "wrap": true,
     "size": "Large",
     "weight": "Bolder"
    }
   ]
  },
  {
   "type": "Container",
   "padding": "Default",
   "items": [
    {
     "type": "TextBlock",
     "text": "Synchronization of your GMM group **${$root.groupName}** has been disabled. If no action is taken, the sync will be deleted on **{{DATE(${$root.jobExpirationDate}, SHORT)}} at {{TIME(${$root.jobExpirationDate})}}**. After this period, if you wish to reenable the sync, you will need to follow GMM's onboarding process again.",
     "wrap": true,
     "color": "Attention"
    },
    {
     "type": "TextBlock",
     "text": "GMM has identified **${$root.changeQuantityForAdditions}** members to be added, increasing the group size by **${$root.changePercentageForAdditions}%**, which is more than the current additions threshold of **${$root.thresholdPercentageForAdditions}%**.",
     "wrap": true,
     "spacing": "Small",
     "color": "Accent",
     "$when": "${$root.changePercentageForAdditions > $root.thresholdPercentageForAdditions}"
    },
    {
     "type": "TextBlock",
     "text": "GMM has identified **${$root.changeQuantityForRemovals}** members to be removed, decreasing the group size by **${$root.changePercentageForRemovals}%**, which is more than the current removals threshold of **${$root.thresholdPercentageForRemovals}%**.",
     "wrap": true,
     "spacing": "Small",
     "color": "Accent",
     "$when": "${$root.changePercentageForRemovals > $root.thresholdPercentageForRemovals}"
    },
    {
     "type": "TextBlock",
     "text": "Do you want to proceed?",
     "wrap": true,
     "color": "Accent",
     "size": "Default",
     "weight": "Bolder"
    },
    {
     "type": "ActionSet",
     "actions": [
      {
       "type": "Action.Http",
       "title": "No, Pause Sync Job",
       "method": "POST",
       "url": "https://${$root.apiHostname}/api/v1/notifications/${$root.notificationId}/resolve",
       "body": "{\"resolution\":\"Paused\"}",
       "isPrimary": true,
       "style": "positive"
      },
      {
       "type": "Action.Http",
       "title": "Yes, Apply Changes",
       "method": "POST",
       "url": "https://${$root.apiHostname}/api/v1/notifications/${$root.notificationId}/resolve",
       "body": "{\"resolution\":\"IgnoreOnce\"}"
      }
     ],
     "spacing": "Large"
    },
    {
     "type": "Container",
     "padding": "Medium",
     "separator": true,
     "items": [
      {
       "type": "TextBlock",
       "text": "**${$root.thresholdPercentageForAdditions}% increase** and **${$root.thresholdPercentageForRemovals}% decrease** alerts are configured for this group. If you would like to change these alert percentages or disable them, please pause the sync and contact GMM support for further inquiry.",
       "wrap": true
      }
     ],
     "spacing": "Medium"
    }
   ],
   "separator": true
  }
 ],
 "autoInvokeAction": {
  "method": "POST",
  "url": "https://${$root.apiHostname}/api/v1/notifications/${$root.notificationId}/card",
  "body": "",
  "type": "Action.Http"
 }
}

