 {
    "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
    "type": "AdaptiveCard",
    "version": "1.4",
    "hideOriginalBody": true,
    "createdUtc": "${$root.cardCreatedTime}",
    "body": [
        {
            "type": "Container",
            "padding": "Small",
            "items": [
                {
                    "type": "ColumnSet",
                    "columns": [
                        {
                            "type": "Column",
                            "padding": "None",
                            "width": "auto",
                            "items": [
                                {
                                    "type": "Image",
                                    "url": "data:image/png;base64,",
                                    "altText": "Synchronization Icon",
                                    "size": "Small"
                                }
                            ]
                        },
                        {
                            "type": "Column",
                            "padding": "None",
                            "width": "auto",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "${$root.titleContent}",
                                    "wrap": true,
                                    "weight": "Bolder"
                                },
                                {
                                    "type": "TextBlock",
                                    "text": "Group Membership Management",
                                    "wrap": true,
                                    "spacing": "None",
                                    "color": "Light",
                                    "size": "Small"
                                }
                            ],
                            "verticalContentAlignment": "Center"
                        }
                    ],
                    "padding": "None"
                }
            ],
            "style": "emphasis"
        },
        {
            "type": "Container",
            "padding": "Default",
            "items": [
                {
                    "type": "TextBlock",
                    "text": "${$root.destinationGroupName}",
                    "wrap": true,
                    "size": "Large",
                    "weight": "Bolder"
                }
            ]
        },
        {
            "type": "Container",
            "padding": "Default",
            "items": [
                {
                    "type": "TextBlock",
                    "text": "${$root.messageContent}",
                    "wrap": true
                }
            ],
            "separator": true
        },
        {
            "type": "Container",
            "items": [
                {
                    "type": "ColumnSet",
                    "columns": [
                        {
                            "type": "Column",
                            "width": "auto",
                            "items": [
                                {
                                    "type": "ActionSet",
                                    "actions": [
                                        {
                                            "type": "Action.OpenUrl",
                                            "title": "Learn more about GMM",
                                            "url": "${$root.DashboardUrl}"
                                        }
                                    ],
                                    "$when": "${$root.DashboardUrl != \"\"}"
                                }
                            ]
                        },
                        {
                            "type": "Column",
                            "width": "stretch"
                        },
                        {
                            "type": "Column",
                            "width": "auto",
                            "items": [
                                {
                                    "type": "ActionSet",
                                    "actions": [
                                        {
                                            "type": "Action.OpenUrl",
                                            "title": "Go to GMM UI",
                                            "url": "${$root.JobUrl}"
                                        }
                                    ],
                                    "$when": "${$root.JobUrl != \"\"}"
                                }
                            ]
                        }
                    ]
                }
            ],
            "separator": true,
            "spacing": "ExtraLarge"
        }
    ],
    "padding": "None",
    "@type": "AdaptiveCard",
    "@context": "http://schema.org/extensions",
    "originator": "${$root.providerId}"
}

You received this notification because you are listed as an owner of **{0}**.

    Membership syncs for **{0}** with Id {1} have been disabled because its following source group object ID(s) are not valid:
{2}
